import { button, badge, emptyState, escapeHtml as e } from "./ui.js";
import { icon } from "./icons.js";
import { panel, metric, select, table } from "./chairman.js";
import { coursesPage } from "./learning.js";
import { demoPassword } from "./parent-login.js";
import { adminViews, adminScope, adminClasses, adminStudents, adminGuardians, adminCourses, adminOverview, adminStudentDetail, adminReportTypes, adminStudentStatuses, adminGuardianStatuses, adminCourseStatuses, visibleAdminReports } from "./admin-data.js";

const choices = (values, current) => values.map(([id, name]) => `<option value="${e(id)}" ${String(id) === String(current) ? "selected" : ""}>${e(name)}</option>`).join("");
const heading = (title, text, actions = "") => `<header class="chairman-page-heading"><div><h1>${title}</h1><p>${text}</p></div><div class="chairman-heading-actions">${badge("Prototype records", "amber")}${actions}</div></header>`;
const link = (view, text) => `<a class="button secondary compact" href="#admin/overview/${view}">${text}</a>`;
function identity(options, scope) {
  const entries = options.state.accounts.flatMap((person) => person.grants.map((grant, index) => ({ person, grant, index }))).filter(({ grant }) => grant.role === "admin");
  const current = options.context.account.id + "|" + options.context.account.grants.indexOf(options.context.grant);
  return `<header class="section-identity"><div><span class="chairman-eyebrow">SCHOOL ADMINISTRATION</span><h1>${e(scope.branch.school)}</h1><p>Admissions, family access and course records · ${e(options.context.account.name)}</p></div><label class="principal-demo-account"><span>Demo School Administrator</span><span class="select-wrap"><select data-change="account" aria-label="Preview School Administrator">${choices(entries.map(({ person, grant, index }) => [person.id + "|" + index, person.name + " · " + options.state.branches.find((branch) => branch.id === grant.branch)?.name]), current)}</select>${icon("chevronDown", 14)}</span></label></header>`;
}
function filters(options, kind) {
  const f = options.schoolAdmin, status = ({ students: ["Student records", "admin-student-status", adminStudentStatuses, f.studentStatus], guardians: ["Guardian links", "admin-guardian-status", adminGuardianStatuses, f.guardianStatus], courses: ["Course readiness", "admin-course-status", adminCourseStatuses, f.courseStatus] })[kind];
  return `<div class="chairman-filters admin-filters">${select("Grade", "admin-grade", [["all", "All school grades"], ...Array.from({ length: 14 }, (_, grade) => [String(grade), grade ? "Grade " + grade : "Preschool"])], f.grade)}${select("Class", "admin-class", [["all", "All matching classes"], ...adminClasses(options.state, options.context, f.grade).map((name) => [name, "Class " + name])], f.className)}${status ? select(status[0], status[1], Object.entries(status[2]), status[3]) : ""}${kind !== "brief" ? `<label class="chairman-search">${icon("search", 16)}<input type="search" data-change="admin-query" data-focus="admin-search" aria-label="Search administration records" value="${e(f.query)}" placeholder="Search ${kind === "courses" ? "course, class or teacher" : "name, admission or class"}"></label>` : ""}</div>`;
}
function studentTable(options, rows) {
  return rows.length ? table(["Student", "Class", "Guardian access", "Courses / learning", "Actions"], rows.map((row) => `<tr><td><button type="button" class="chairman-person-link" data-action="admin-student" data-value="${e(row.student.id)}">${e(row.student.name)}</button><small>${e(row.student.admissionNumber)}</small></td><td>Class ${e(row.student.className)}</td><td>${row.guardians.map((person) => e(person.name)).join(", ") || badge("Guardian needed", "amber")}</td><td>${row.courses.length} courses<small>${row.completed} / ${row.materials} materials done</small></td><td>${button("Edit student", "edit-student", { value: row.student.id, variant: "secondary compact" })}</td></tr>`).join(""), "School admission register") : emptyState("users", "No student records match", "Try another grade, class or record filter, or register a new student.");
}
function overview(options) {
  const data = adminOverview(options.state, options.context);
  return heading("Administration Overview", "Keep student records, guardian access and course enrolments ready for the school day.", button("Register student", "edit-student", { iconName: "plus" })) + `<div class="chairman-metrics">${metric("Registered students", data.students.length, "Editable admission records", "users")}${metric("Guardian accounts", data.guardians.length, "Parent appointments in this school", "badge", "blue")}${metric("School courses", data.courses.length, "Existing courses and teacher assignments", "book")}${metric("Parent access linked", data.students.length ? Math.round((data.students.length-data.missingGuardians)/data.students.length*100) + "%" : "—", (data.students.length-data.missingGuardians) + " students with a valid guardian", "checkCircle")}</div><div class="section-summary-strip"><div><span>Guardian link needed</span><strong>${data.missingGuardians}</strong></div><div><span>Students without courses</span><strong>${data.noCourses}</strong></div><div><span>Courses needing a teacher</span><strong>${data.unassigned}</strong></div><div><span>Classes with records</span><strong>${data.classes.length}</strong></div></div><div class="section-attention"><div><h2>Record readiness</h2><p>${data.missingGuardians} students need a guardian link; ${data.noCourses} have no matching-class course enrolment.</p></div>${link("students", "Review admissions")}</div>` + panel("Class record coverage", "Actual admission and course records in your school", data.classes.length ? table(["Class", "Registered students", "Guardian access linked", "Enrolled in a course", "School courses"], data.classes.map((row) => `<tr><td>Class ${e(row.className)}</td><td>${row.students}</td><td>${row.guardians}</td><td>${row.enrolled}</td><td>${row.courses}</td></tr>`).join(""), "Class record coverage") : emptyState("school", "No school records yet", "Start by registering a student.")) + panel("Recent record updates", "Student and course administration in this browser", data.activity.length ? `<div class="admin-activity">${data.activity.map((item) => `<article>${icon("checkCircle", 18)}<div><strong>${e(item.message)}</strong><small>${e(item.actor)} · ${e(item.at.slice(0, 16).replace("T", " "))} UTC</small></div></article>`).join("")}</div>` : emptyState("file", "No record updates yet", "Saved student and course changes will appear here."));
}
function students(options) {
  const f = options.schoolAdmin, rows = adminStudents(options.state, options.context, f), page = Math.min(f.page, Math.max(1, Math.ceil(rows.length/12))), start = (page-1)*12;
  return heading("Admissions & Students", "Register admissions, maintain class placement and link existing guardian accounts.", button("Register student", "edit-student", { iconName: "plus" })) + filters(options, "students") + panel("Student admission register", rows.length + " matching records · Admission numbers are unique across the network", studentTable(options, rows.slice(start,start+12)) + `<div class="chairman-pager"><span>${rows.length ? start+1 : 0}–${Math.min(start+12,rows.length)} of ${rows.length}</span><div>${button("Previous", "admin-page", { value: page-1, variant: "secondary compact", extra: page<=1 ? "disabled" : "" })}<span>Page ${page}</span>${button("Next", "admin-page", { value: page+1, variant: "secondary compact", extra: start+12>=rows.length ? "disabled" : "" })}</div></div>`);
}
function guardians(options) {
  const rows = adminGuardians(options.state, options.context, options.schoolAdmin), students = adminStudents(options.state, options.context, { ...options.schoolAdmin, query: "", studentStatus: "missing_guardian" });
  return heading("Guardians & Access", "Review parent-account links and help families use student admission login.") + filters(options, "guardians") + `<div class="admin-access-note surface">${icon("badge", 24)}<div><h2>Parent demo access</h2><p>A linked guardian signs in with the student’s admission number and temporary demo password <strong>${e(demoPassword)}</strong>. Guardian appointments are managed by the Principal or Chairman.</p></div></div>` + panel("Guardian account directory", "Only parent appointments and student links in this school", rows.length ? table(["Guardian account", "Linked students", "Access", "Action"], rows.map((row) => `<tr><td><strong>${e(row.person.name)}</strong></td><td>${row.students.map((student) => `<strong>${e(student.name)}</strong><small>${e(student.admissionNumber)} · Class ${e(student.className)}</small>`).join("") || "No linked students"}</td><td>${badge(row.students.length ? "Student login linked" : "Link needed", row.students.length ? "green" : "amber")}</td><td>${button("View guardian links", "admin-guardian", { value: row.person.id, variant: "secondary compact" })}</td></tr>`).join(""), "School guardian directory") : emptyState("users", "No matching guardian accounts", "A Principal can appoint parent accounts in this school.")) + panel("Students needing a guardian link", "Matching grade/class selection · Link an existing school guardian through Edit student", studentTable(options, students));
}
function courses(options) {
  const rows = adminCourses(options.state, options.context, options.schoolAdmin);
  return heading("Courses & Enrolment", "Assign school teachers and matching-class students to existing courses.") + filters(options, "courses") + panel("School course administration", "Teacher and student assignments update teaching and parent portals", rows.length ? table(["Course", "Teacher", "Enrolled", "Materials", "Done / assigned", "Actions"], rows.map((row) => `<tr><td><strong>${e(row.course.title)}</strong><small>${e(row.course.code)} · Class ${e(row.course.className)}</small></td><td>${e(row.teacher?.name || "No eligible teacher")}</td><td>${row.students.length}</td><td>${row.materials}</td><td>${row.completed} / ${row.expected}</td><td><div class="section-row-actions">${button("Edit assignment", "assign", { value: row.course.id, variant: "secondary compact" })}${button("Materials & progress", "open-course", { value: row.course.id, variant: "secondary compact" })}</div></td></tr>`).join(""), "School course administration") : emptyState("book", "No matching courses", "Try another grade, class or course-readiness filter."));
}
export function adminReportPreview(report) {
  const c=report.criteria,s=report.summary;
  return `<article class="admin-report-preview section-report-preview"><div class="admin-report-brand"><strong>Sussex College Network</strong>${badge("SAMPLE · PROTOTYPE", "amber")}</div><h2>${e(report.title)}</h2><p>${e(report.owner.school)} · School Administrator: ${e(report.owner.by)}</p><p>Snapshot: ${e(c.to)} · ${c.grade === "all" ? "All grades" : "Grade " + e(c.grade)} · ${c.className === "all" ? "All matching classes" : "Class " + e(c.className)}</p>${report.type !== "brief" ? `<p>Search: ${e(c.query || "All records")} · ${e(({students:adminStudentStatuses[c.studentStatus],guardians:adminGuardianStatuses[c.guardianStatus],courses:adminCourseStatuses[c.courseStatus]})[report.type])}</p>` : ""}<div class="section-summary-strip"><div><span>Student records</span><strong>${s.students}</strong></div><div><span>Guardian accounts</span><strong>${s.guardians}</strong></div><div><span>School courses</span><strong>${s.courses}</strong></div><div><span>Student access linked</span><strong>${s.ready}</strong></div></div>${table(report.customColumns.map(([,label])=>label),report.customRows.map((row)=>`<tr>${report.customColumns.map(([key])=>`<td>${e(row[key] ?? "—")}</td>`).join("")}</tr>`).join(""),"Administration report data")}<p class="chairman-filter-note">Browser-local admission, guardian and course records at capture time. Row filters apply to the selected report type. Private discussion/review notes, passwords, generated marks and attendance data are excluded.</p></article>`;
}
export function adminReportHTML(report,logo="") {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(report.title)} · Sussex College Network</title><style>body{font:14px Arial,sans-serif;color:#183a32;max-width:1120px;margin:36px auto;padding:0 24px}img{width:66px;float:right}h2{font-size:27px}table{width:100%;border-collapse:collapse;margin:24px 0}td,th{text-align:left;border-bottom:1px solid #dce6e1;padding:10px}th{background:#edf4f0}.table-scroll{overflow:auto}.section-summary-strip{display:flex;justify-content:space-between;gap:20px;background:#edf4f0;padding:20px}.section-summary-strip span{display:block;font-size:12px}.section-summary-strip strong{font-size:22px}.chairman-filter-note{color:#52685f;font-size:12px}.badge{display:inline-block;margin:8px;color:#825414}@media print{body{margin:0;max-width:none}tr{break-inside:avoid}thead{display:table-header-group}}@page{size:A4 landscape;margin:14mm}</style></head><body>${logo?`<img alt="Sussex College Network logo" src="${e(logo)}">`:""}${adminReportPreview(report)}<footer>School Administration · Generated ${e(report.generatedAt)}</footer></body></html>`;
}
function reports(options,scope) {
  const f=options.schoolAdmin, reports=visibleAdminReports(options.state,options.context),current=reports.find((item)=>item.id===f.reportId);
  return heading("Administration Reports","Capture admission, guardian and course records for school administration.")+`<div class="section-report-builder surface"><div>${select("Report type","admin-report-type",Object.entries(adminReportTypes),f.reportType)}</div>${filters(options,f.reportType)}<div class="section-report-generate"><p>${icon("school",17)}${e(scope.branch.name)} · Assigned school only</p>${button("Generate administration report","admin-generate-report",{iconName:"file"})}</div></div><section class="surface chairman-report-result"><div class="chairman-report-actions">${current?select("Download format","admin-report-format",[["csv","CSV spreadsheet"],["html","Standalone HTML"]],f.reportFormat)+button("Download report","admin-download-report",{value:current.id,variant:"secondary",iconName:"download"})+button("Print / Save PDF","admin-print-report",{value:current.id,variant:"secondary",iconName:"file"}):"Report preview"}</div>${current?adminReportPreview(current):emptyState("file","Your school administration report starts here","Select a report and filters, then generate a snapshot.")}</section>`+panel("Saved school administration snapshots","Latest eight per appointed school · Separate from academic and executive reports",`<div class="chairman-report-history">${reports.map((item)=>`<button type="button" class="chairman-history-card ${current?.id===item.id?"is-selected":""}" data-action="admin-open-report" data-value="${item.id}">${icon("file",20)}<span><strong>${e(item.title)}</strong><small>${e(item.criteria.to)} · ${item.customRows.length} rows</small></span>${badge("Sample","neutral")}</button>`).join("")||'<p class="chairman-no-history">Generated administration reports will appear here.</p>'}</div>`);
}
export function schoolAdminPage(options) {
  const scope=adminScope(options.state,options.context);
  if(!scope)return emptyState("school","No administrator appointment","An active School Administrator school appointment is required.");
  const view=options.schoolAdmin.view;
  return `<section class="chairman-portal section-portal school-admin-portal">${identity(options,scope)}<nav class="chairman-view-bar section-view-bar" aria-label="School Administrator views">${adminViews.map((item)=>`<a href="#admin/overview/${item.id}" aria-label="${item.name}" ${item.id===view?'aria-current="page" class="is-active"':""}>${icon(item.icon,18)}<span class="chairman-view-full">${item.name}</span><span class="chairman-view-short">${item.short}</span></a>`).join("")}</nav><div class="chairman-analytics section-analytics">${adminCourses(options.state,options.context).some((row)=>row.course.id===options.courseId)?coursesPage(options):({summary:overview,students,guardians,courses,reports})[view](options,scope)}</div></section>`;
}
export function adminStudentPanel(options,student) {
  const row=adminStudentDetail(options.state,options.context,student);
  return `<div class="form-body admin-student-profile"><h3>${e(student.name)}</h3><p>${e(student.admissionNumber)} · Class ${e(student.className)}</p><div class="admin-profile-facts"><div><span>Linked guardians</span><strong>${e(row.guardians.map((person)=>person.name).join(", ")||"No guardian linked")}</strong></div><div><span>Learning completion</span><strong>${row.completed} / ${row.materials} materials</strong></div><div><span>Parent demo access</span><strong>${row.loginReady?"Linked admission login":"Guardian link needed"}</strong></div></div><h3>Enrolled courses</h3>${row.courses.map((course)=>`<p>${e(course.title)} · Class ${e(course.className)}</p>`).join("")||'<p>No matching-class course enrolment.</p>'}${row.loginReady?`<p class="chairman-filter-note">Parent demo login: ${e(student.admissionNumber)} · Temporary password ${e(demoPassword)}</p>`:""}</div><footer class="dialog-actions">${button("Close","close-dialog",{variant:"secondary"})}${button("Edit student","edit-student",{value:student.id})}</footer>`;
}
export function adminGuardianPanel(options,person) {
  const row=adminGuardians(options.state,options.context).find((row)=>row.person.id===person.id);
  return `<div class="form-body"><h3>${e(person.name)}</h3><p class="chairman-filter-note">Parent appointment in ${e(adminScope(options.state,options.context).branch.name)}. Update links through the student record.</p><div class="admin-guardian-links">${row.students.map((student)=>`<article><div><strong>${e(student.name)}</strong><small>${e(student.admissionNumber)} · Class ${e(student.className)}</small></div>${button("Edit student","edit-student",{value:student.id,variant:"secondary compact"})}</article>`).join("")||emptyState("users","No student links","Link this existing guardian from a student record.")}</div></div><footer class="dialog-actions">${button("Close","close-dialog",{variant:"secondary"})}</footer>`;
}
